// src/components/InternshipCard.jsx
import React from 'react';
import PropTypes from 'prop-types';
import { Link } from 'react-router-dom';
import Button from './Button'; // تأكد من المسار الصحيح لمكون الزر

const InternshipCard = ({ opportunity }) => {
  // للحد من طول الوصف إذا كان طويلاً جداً
  const truncateDescription = (description, maxLength = 100) => {
    if (description.length > maxLength) {
      return description.substring(0, maxLength) + '...';
    }
    return description;
  };

  return (
    <div className="bg-white rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300 p-6 border border-gray-200 flex flex-col justify-between">
      <div>
        <h3 className="text-xl font-bold text-darkText mb-2">{opportunity.title}</h3>
        <p className="text-gray-700 text-lg mb-1">{opportunity.company}</p>
        <p className="text-gray-500 text-sm mb-3">
          <i className="fas fa-map-marker-alt mr-1"></i> {opportunity.location}
        </p>

        <div className="flex flex-wrap gap-2 mb-4">
          {opportunity.skills && opportunity.skills.map((skill, index) => (
            <span key={index} className="bg-primaryLight text-primary text-xs font-medium px-2.5 py-0.5 rounded-full">
              {skill}
            </span>
          ))}
        </div>

        <p className="text-gray-600 mb-4 text-sm">
          {truncateDescription(opportunity.description)}
        </p>

        <ul className="text-sm text-gray-600 mb-4 space-y-1">
          <li>
            <i className="far fa-clock mr-2"></i>
          Duration: {opportunity.duration}
          </li>
          <li>
            <i className="fas fa-money-bill-wave mr-2"></i>
            <button
              type="reset"
              class="btn btn-primary"
            >
              
            </button>
            reward: {opportunity.stipend}
          </li>
          <li>
            <i className="far fa-calendar-alt mr-2"></i>
            ت: {opportunity.postedDate}
          </li>
        </ul>
      </div>

      <div className="mt-4">
        {}
        <Link to={`/opportunities/${opportunity.id}`}>
          <Button variant="primary" className="w-full">
             View details
          </Button>
        </Link>
      </div>
    </div>
  );
};

InternshipCard.propTypes = {
  opportunity: PropTypes.shape({
    id: PropTypes.string.isRequired, // تم تغييرها إلى string لأن الـ id في بياناتك هي string
    title: PropTypes.string.isRequired,
    company: PropTypes.string.isRequired,
    location: PropTypes.string.isRequired,
    duration: PropTypes.string.isRequired,
    stipend: PropTypes.string.isRequired,
    skills: PropTypes.arrayOf(PropTypes.string),
    description: PropTypes.string.isRequired,
    postedDate: PropTypes.string.isRequired,
  }).isRequired,
};

export default InternshipCard;
